<TABLE cellpadding=0 cellspacing=0 class="t5">
<TR>
	<TD rowspan=2 class="tr8 td27"><SPAN class="p29 ft1">2</SPAN> </TD>
	<TD rowspan=2 class="tr8 td28"><SPAN class="p21 ft1">Förslag till lag om kommunal</SPAN> </TD>
	<TD class="tr2 td29"><SPAN class="p3 ft3">Prop. 2025/26:234</SPAN> </TD>
